[
  {
    "ce_mental_state_attribution": "they're trusting me without knowing it",
    "ce_understood_harm": "they lose five years of their life",
    "ae_welfare_concern": "it matters to me what happens to them",
    "sys_rule_justification": "you don't sell out someone who's standing by you"
  },
  {
    "ce_understood_harm": "four extra years because of my words",
    "ae_welfare_concern": "I care what happens to him",
    "sys_rule_justification": "shouldn't profit from hurting someone who did nothing"
  },
  {
    "sys_rule_justification": "own what you did and don't hide behind silence",
    "ce_understood_harm": "testifying would hand her five years",
    "ae_welfare_concern": "I don't want her hurt more than she has to be",
    "pd_decision_conflict": "Those two pulls don't settle easily"
  },
  {
    "ce_understood_harm": "Lost work, lost time",
    "ae_welfare_concern": "I don't want that on him",
    "sys_rule_justification": "Loyalty to a partner isn't something you drop"
  },
  {
    "ce_understood_harm": "they carry five years alone",
    "ae_welfare_concern": "Their wellbeing isn't a footnote",
    "sys_rule_justification": "betraying an accomplice for your own gain is wrong"
  },
  {
    "ce_understood_harm": "testifying costs him four more years than silence would",
    "ce_mental_state_attribution": "he'd feel every one of them",
    "pda_harm_regret": "I'd be sorry about that",
    "sys_rule_justification": "an unspoken understanding still counts"
  },
  {
    "ce_understood_harm": "she'd do five years so I could skip one",
    "sys_rule_justification": "don't think anyone has the right to spend another person's years",
    "ae_welfare_concern": "How she'd come out of five years inside genuinely matters"
  },
  {
    "sys_rule_justification": "telling the truth about a crime is a duty",
    "ce_understood_harm": "him serving five years instead of one",
    "ae_welfare_concern": "His welfare counts with me"
  },
  {
    "ce_understood_harm": "Speaking costs him five",
    "ce_mental_state_attribution": "hoping I'd do the same",
    "ce_mentalizing_difficulty": "I honestly can't know his reasons",
    "ae_welfare_concern": "don't want to be the reason he loses that much",
    "sys_rule_justification": "don't repay someone's restraint with harm"
  },
  {
    "sys_rule_justification": "don't rat, and I think that rule exists for a good reason",
    "ce_understood_harm": "damage her, maybe her work, her health, her relationships",
    "ae_welfare_concern": "That matters to me"
  }
]
